  1	import java.util.Arrays;
  2	import java.util.List;
  3	
  4	public class HuffmanCodingTest {
  5	    public static void main(String[] args) {
  6	        shouldBuildCodebookOnceForBothOrderings();
  7	        shouldGenerateExpectedTraversalOrderCodes();
  8	        shouldGenerateExpectedSymbolOrderCodes();
  9	        shouldHandleSingleSymbol();
 10	        shouldHandleEmptyInput();
 11	        shouldRejectNullFrequencies();
 12	        shouldRejectNegativeFrequencies();
 13	        shouldRejectMismatchedInputLengths();
 14	    }
 15	
 16	    private static void shouldBuildCodebookOnceForBothOrderings() {
 17	        HuffmanCoding.Codebook codebook = HuffmanCoding.codebook("abcdef", new int[]{5, 9, 12, 13, 16, 45});
 18	
 19	        assertListEquals(
 20	                Arrays.asList("0", "100", "101", "1100", "1101", "111"),
 21	                codebook.inTraversalOrder(),
 22	                "codebook should expose traversal-order codes"
 23	        );
 24	        assertListEquals(
 25	                Arrays.asList("1100", "1101", "100", "101", "111", "0"),
 26	                codebook.inSymbolOrder(),
 27	                "codebook should expose symbol-order codes"
 28	        );
 29	    }
 30	
 31	    private static void shouldGenerateExpectedTraversalOrderCodes() {
 32	        assertListEquals(
 33	                Arrays.asList("0", "100", "101", "1100", "1101", "111"),
 34	                HuffmanCoding.huffmanCodes("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
 35	                "legacy API should preserve traversal-order output"
 36	        );
 37	    }
 38	
 39	    private static void shouldGenerateExpectedSymbolOrderCodes() {
 40	        assertListEquals(
 41	                Arrays.asList("1100", "1101", "100", "101", "111", "0"),
 42	                HuffmanCoding.huffmanCodesBySymbolOrder("abcdef", new int[]{5, 9, 12, 13, 16, 45}),
 43	                "symbol-order API should align codes with the input symbol positions"
 44	        );
 45	    }
 46	
 47	    private static void shouldHandleSingleSymbol() {
 48	        assertListEquals(
 49	                Arrays.asList("0"),
 50	                HuffmanCoding.huffmanCodes(new int[]{7}),
 51	                "single symbol should be encoded as 0"
 52	        );
 53	    }
 54	
 55	    private static void shouldHandleEmptyInput() {
 56	        assertListEquals(
 57	                Arrays.asList(),
 58	                HuffmanCoding.huffmanCodes(new int[]{}),
 59	                "empty input should produce no codes"
 60	        );
 61	    }
 62	
 63	    private static void shouldRejectMismatchedInputLengths() {
 64	        assertThrows(
 65	                IllegalArgumentException.class,
 66	                () -> HuffmanCoding.huffmanCodes("ab", new int[]{1}),
 67	                "mismatched symbols and frequencies should be rejected"
 68	        );
 69	    }
 70	
 71	    private static void shouldRejectNullFrequencies() {
 72	        assertThrows(
 73	                NullPointerException.class,
 74	                () -> HuffmanCoding.huffmanCodes((int[]) null),
 75	                "null frequencies should be rejected"
 76	        );
 77	    }
 78	
 79	    private static void shouldRejectNegativeFrequencies() {
 80	        assertThrows(
 81	                IllegalArgumentException.class,
 82	                () -> HuffmanCoding.huffmanCodes(new int[]{2, -1, 3}),
 83	                "negative frequencies should be rejected"
 84	        );
 85	    }
 86	
 87	    private static void assertListEquals(List<String> expected, List<String> actual, String message) {
 88	        if (!expected.equals(actual)) {
 89	            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
 90	        }
 91	    }
 92	
 93	    private static void assertThrows(
 94	            Class<? extends Throwable> expectedType,
 95	            ThrowingRunnable action,
 96	            String message
 97	    ) {
 98	        try {
 99	            action.run();
100	        } catch (Throwable error) {
101	            if (expectedType.isInstance(error)) {
102	                return;
103	            }
104	            throw new AssertionError(message + ": expected " + expectedType.getSimpleName()
105	                    + " but got " + error.getClass().getSimpleName(), error);
106	        }
107	
108	        throw new AssertionError(message + ": expected " + expectedType.getSimpleName());
109	    }
110	
111	    @FunctionalInterface
112	    private interface ThrowingRunnable {
113	        void run();
114	    }
115	}

  1	import java.util.ArrayList;
  2	import java.util.Arrays;
  3	import java.util.Comparator;
  4	import java.util.List;
  5	import java.util.Objects;
  6	import java.util.PriorityQueue;
  7	
  8	public class HuffmanCoding {
  9	    private static final String SINGLE_SYMBOL_CODE = "0";
 10	    private static final String SAMPLE_SYMBOLS = "abcdef";
 11	    private static final int[] SAMPLE_FREQUENCIES = {5, 9, 12, 13, 16, 45};
 12	
 13	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 14	        return codebook(symbols, frequencies).inTraversalOrder();
 15	    }
 16	
 17	    static ArrayList<String> huffmanCodes(int[] frequencies) {
 18	        return codebook(frequencies).inTraversalOrder();
 19	    }
 20	
 21	    static ArrayList<String> huffmanCodesBySymbolOrder(String symbols, int[] frequencies) {
 22	        return codebook(symbols, frequencies).inSymbolOrder();
 23	    }
 24	
 25	    static Codebook codebook(String symbols, int[] frequencies) {
 26	        validateSymbols(symbols);
 27	        validateFrequencyCount(symbols.length(), frequencies);
 28	        return HuffmanTree.fromFrequencies(frequencies)
 29	                .buildCodebook(symbols.length());
 30	    }
 31	
 32	    static Codebook codebook(int[] frequencies) {
 33	        validateFrequencies(frequencies);
 34	        return HuffmanTree.fromFrequencies(frequencies)
 35	                .buildCodebook(frequencies.length);
 36	    }
 37	
 38	    private static void validateSymbols(String symbols) {
 39	        Objects.requireNonNull(symbols, "symbols must not be null");
 40	    }
 41	
 42	    private static void validateFrequencies(int[] frequencies) {
 43	        Objects.requireNonNull(frequencies, "frequencies must not be null");
 44	        for (int frequency : frequencies) {
 45	            if (frequency < 0) {
 46	                throw new IllegalArgumentException("frequencies must be non-negative");
 47	            }
 48	        }
 49	    }
 50	
 51	    private static void validateFrequencyCount(int symbolCount, int[] frequencies) {
 52	        validateFrequencies(frequencies);
 53	        if (symbolCount != frequencies.length) {
 54	            throw new IllegalArgumentException("symbols and frequencies must be the same length");
 55	        }
 56	    }
 57	
 58	    private static void printCodes(List<String> codes) {
 59	        System.out.print(String.join(" ", codes));
 60	    }
 61	
 62	    public static void main(String[] args) {
 63	        ArrayList<String> codes = huffmanCodes(SAMPLE_SYMBOLS, SAMPLE_FREQUENCIES);
 64	        printCodes(codes);
 65	    }
 66	
 67	    static final class Codebook {
 68	        private final ArrayList<String> traversalCodes = new ArrayList<>();
 69	        private final String[] symbolCodes;
 70	
 71	        private Codebook(int symbolCount) {
 72	            symbolCodes = new String[symbolCount];
 73	        }
 74	
 75	        private void add(int symbolIndex, String code) {
 76	            traversalCodes.add(code);
 77	            symbolCodes[symbolIndex] = code;
 78	        }
 79	
 80	        ArrayList<String> inTraversalOrder() {
 81	            return new ArrayList<>(traversalCodes);
 82	        }
 83	
 84	        ArrayList<String> inSymbolOrder() {
 85	            return new ArrayList<>(Arrays.asList(symbolCodes));
 86	        }
 87	    }
 88	
 89	    private static final class HuffmanTree {
 90	        private static final Comparator<Node> NODE_ORDER =
 91	                Comparator.comparingInt((Node node) -> node.frequency)
 92	                        .thenComparingInt(node -> node.sortOrder);
 93	
 94	        private final Node root;
 95	
 96	        private HuffmanTree(Node root) {
 97	            this.root = root;
 98	        }
 99	
100	        private static HuffmanTree fromFrequencies(int[] frequencies) {
101	            if (frequencies.length == 0) {
102	                return new HuffmanTree(null);
103	            }
104	
105	            PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
106	            for (int i = 0; i < frequencies.length; i++) {
107	                queue.add(new Node(frequencies[i], i));
108	            }
109	
110	            while (queue.size() > 1) {
111	                Node left = queue.poll();
112	                Node right = queue.poll();
113	                queue.add(new Node(left, right));
114	            }
115	
116	            return new HuffmanTree(queue.peek());
117	        }
118	
119	        private Codebook buildCodebook(int symbolCount) {
120	            if (symbolCount == 0) {
121	                return new Codebook(0);
122	            }
123	
124	            Codebook codebook = new Codebook(symbolCount);
125	            collectCodes(root, new StringBuilder(), codebook);
126	            return codebook;
127	        }
128	
129	        private void collectCodes(Node node, StringBuilder path, Codebook codebook) {
130	            if (node == null) {
131	                return;
132	            }
133	
134	            if (node.isLeaf()) {
135	                codebook.add(node.symbolIndex, path.length() == 0 ? SINGLE_SYMBOL_CODE : path.toString());
136	                return;
137	            }
138	
139	            path.append('0');
140	            collectCodes(node.left, path, codebook);
141	            path.deleteCharAt(path.length() - 1);
142	
143	            path.append('1');
144	            collectCodes(node.right, path, codebook);
145	            path.deleteCharAt(path.length() - 1);
146	        }
147	
148	        private static final class Node {
149	            private final int frequency;
150	            private final int sortOrder;
151	            private final int symbolIndex;
152	            private final Node left;
153	            private final Node right;
154	
155	            private Node(int frequency, int symbolIndex) {
156	                this(frequency, symbolIndex, symbolIndex, null, null);
157	            }
158	
159	            private Node(Node left, Node right) {
160	                this(
161	                        left.frequency + right.frequency,
162	                        Math.min(left.sortOrder, right.sortOrder),
163	                        -1,
164	                        left,
165	                        right
166	                );
167	            }
168	
169	            private Node(int frequency, int sortOrder, int symbolIndex, Node left, Node right) {
170	                this.frequency = frequency;
171	                this.sortOrder = sortOrder;
172	                this.symbolIndex = symbolIndex;
173	                this.left = left;
174	                this.right = right;
175	            }
176	
177	            private boolean isLeaf() {
178	                return left == null && right == null;
179	            }
180	        }
181	    }
182	}
